-- Link each event to the reusable verified scorecard used by Hole View.\nalter table public.events\n  add column if not exists course_scorecard_id uuid\n  references public.course_scorecards(id) on delete set null;\n\nupdate public.events e\nset course_scorecard_id = c.id\nfrom public.course_scorecards c\nwhere e.course_scorecard_id is null\n  and lower(trim(e.venue)) = lower(trim(c.course_name))\n  and lower(trim(coalesce(nullif(e.selected_course_name, ''), 'Main course'))) = lower(trim(c.course_layout));\n